    out = subprocess.run(['curl','-s',url,'-H','Authorization: Bearer <TOKEN>'],capture_output=True,text=True).stdout
    return json.loads(out)

found = []
def walk(fid, name):
    data = get(f'https://api.box.com/2.0/folders/{fid}?limit=1000&fields=id,name,collections,item_collection')
    entries = data.get('item_collection',{}).get('entries',[])
    total = data.get('item_collection',{}).get('total_count')
    cols = [c.get('name') for c in data.get('collections',[])]
    if 'Legal Hold' in cols:
        found.append((fid,name,cols,total,entries))
    for e in entries:
        if e.get('type')=='folder':
            walk(e['id'], e.get('name'))

walk('0','All Files')
for f in found:
    print(f)
